=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(105.2890625 118)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">0.20</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"117.2890625\" y1=\"152\" x2=\"385\" y2=\"152\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"111.2890625\" y1=\"152\" x2=\"123.2890625\" y2=\"152\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(105.2890625 158)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">0.15</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"117.2890625\" y1=\"192\" x2=\"385\" y2=\"192\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"111.2890625\" y1=\"192\" x2=\"123.2890625\" y2=\"192\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(105.2890625 198)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">0.10</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"117.2890625\" y1=\"232\" x2=\"385\" y2=\"232\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"111.2890625\" y1=\"232\" x2=\"123.2890625\" y2=\"232\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(105.2890625 238)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">0.05</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"117.2890625\" y1=\"272\" x2=\"385\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"111.2890625\" y1=\"272\" x2=\"123.2890625\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(105.2890625 278)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">0</text><text text-anchor=\"middle\" transform=\"translate(24 172) rotate(-90)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Radial growth </text><text text-anchor=\"middle\" transform=\"translate(48 172) rotate(-90)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">(centimeters per year)</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"117.2890625\" y1=\"72\" x2=\"117.2890625\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"144.06015625\" y=\"104\" height=\"168\" width=\"26.77109375\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"170.83125\" y=\"144\" height=\"128\" width=\"26.77109375\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(180.75125 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">current</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"224.37343750000002\" y=\"124\" height=\"148\" width=\"26.77109375\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"251.14453125000003\" y=\"152\" height=\"120\" width=\"26.77109375\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(261.06453125 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">moderate change</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"304.68671875\" y=\"224\" height=\"48\" width=\"26.77109375\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"331.4578125\" y=\"240\" height=\"32\" width=\"26.77109375\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(341.3778125 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">extreme change</text><text text-anchor=\"middle\" transform=\"translate(251.14453125 24)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Modeled Radial Growth of </text><text text-anchor=\"middle\" transform=\"translate(251.14453125 48)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Sugar Maple Trees</text><text text-anchor=\"middle\" transform=\"translate(251.14453125 410.77701171875)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Climate scenario</text><rect xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" x=\"120.59765625\" y=\"427.93701171875\" height=\"71\" width=\"173.8046875\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"127.59765625\" y=\"439.93701171875\" height=\"12\" width=\"12\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text transform=\"translate(149.59765625 451.93701171875)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> with nitrogen</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"127.59765625\" y=\"471.93701171875\" height=\"12\" width=\"12\" fill=\"#333333\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text transform=\"translate(149.59765625 483.93701171875)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> without nitrogen</text></g></svg></figure><div class=\"sr-only\" role=\"region\" aria-label=\"Long description for bar graph titled Modeled Radial Growth of Sugar Maple Trees\"><ul>\n<li>For each data category, the following bars are shown:<br/>\n<ul>\n<li>with nitrogen</li>\n<li>without nitrogen</li>\n</ul>\n</li>\n<li>All values are approximate.</li>\n<li>The data for the 3 categories are as follows:<br/>\n<ul>\n<li>current:<br/>\n<ul>\n<li>with nitrogen: 0.21 centimeters per year</li>\n<li>without nitrogen: 0.16 centimeters per year</li>\n</ul>\n</li>\n<li>moderate change:<br/>\n<ul>\n<li>with nitrogen: 0.19 centimeters per year</li>\n<li>without nitrogen: 0.15 centimeters per year</li>\n</ul>\n</li>\n<li>extreme change:<br/>\n<ul>\n<li>with nitrogen: 0.06 centimeters per year</li>\n<li>without nitrogen: 0.04 centimeters per year</li>\n</ul>\n</li>\n</ul>\n</li>\n</ul></div>\n<p>In&eacute;s Ib&aacute;&ntilde;ez and colleagues studied a forest site in which some sugar maple trees receive periodic fertilization with nitrogen to mimic the broader trend of increasing anthropogenic nitrogen deposition in soil. Ib&aacute;&ntilde;ez and colleagues modeled the radial growth of the trees with and without nitrogen fertilization under three different climate scenarios (the current climate, moderate change, and extreme change). Although they found that climate change would negatively affect growth, they concluded that anthropogenic nitrogen deposition could more than offset that effect provided that change is moderate rather than extreme.</p>","stem":"<p>Which choice best describes data from the graph that support Ib&aacute;&ntilde;ez and colleagues&rsquo; conclusion?</p>","answerOptions":[{"id":"1b80b4df-631a-4f4e-b912-95f86ea591b8","content":"<p>Growth with nitrogen under the current climate exceeded growth with nitrogen under moderate change, but the latter exceeded growth without nitrogen under extreme change.&nbsp;</p>"},{"id":"d1ab2330-862b-4e89-9fdf-a653999b7e26","content":"<p>Growth without nitrogen under the current climate exceeded growth without nitrogen under moderate change, but the latter exceeded growth with nitrogen under extreme change.&nbsp;</p>"},{"id":"2cd4ad1e-d55c-4903-902e-e1d55de04fcf","content":"<p>Growth with nitrogen under moderate change exceeded growth without nitrogen under moderate change, but the latter exceeded growth without nitrogen under extreme change.&nbsp;</p>"},{"id":"9b09f168-5f33-423c-880e-7701daeeb054","content":"<p>Growth with nitrogen under moderate change exceeded growth without nitrogen under the current climate, but the latter exceeded growth with nitrogen under extreme change.&nbsp;</p>"}],"keys":["9b09f168-5f33-423c-880e-7701daeeb054"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it describes data from the graph that support Ib&aacute;&ntilde;ez and colleagues&rsquo; conclusion that increasing anthropogenic nitrogen deposition can compensate for the negative effect of climate change on tree growth if that change is moderate but not if it&rsquo;s extreme. The bar graph shows the growth of sugar maple trees with and without nitrogen fertilization under three different climate-change scenarios: current conditions, a moderate change, and an extreme change. According to the graph, radial growth without nitrogen fertilization is projected to be about 0.16 centimeters (cm) under current conditions, 0.15 cm under a moderate change, and 0.04 cm under an extreme change. The graph also shows that with nitrogen fertilization, growth is projected to be about 0.18 centimeters under a moderate change but only about 0.06 centimeters under an extreme change. Thus, the data in the graph support the researchers&rsquo; conclusion by showing greater growth for a moderate change using nitrogen fertilization than they do either under current conditions without nitrogen fertilization or under an extreme change with nitrogen fertilization.</p><p>Choice A is incorrect. Although it accurately represents the data in the graph, this fact pattern doesn&rsquo;t support Ib&aacute;&ntilde;ez and colleagues&rsquo; conclusion that the decline in radial growth due to climate change will be partly offset by higher levels of anthropogenic nitrogen, but only if change to the climate is moderate and not if it&rsquo;s extreme. To support this would require comparing radial growth without nitrogen fertilization under current climate conditions to the growth with nitrogen fertilization under both moderate and extreme changes. This choice mentions only growth with nitrogen fertilization under current climate conditions and moderate change and growth without nitrogen fertilization under an extreme change, which don&rsquo;t provide a basis to determine whether higher nitrogen in the future will be able to offset reduced growth due to climate change. Choice B is incorrect. Although it accurately represents the data in the graph, this fact pattern doesn&rsquo;t support Ib&aacute;&ntilde;ez and colleagues&rsquo; conclusion that the decline in radial growth due to climate change will be partly offset by higher levels of atmospheric nitrogen, but only if change to the climate is moderate and not if it&rsquo;s extreme. The support needed would compare radial growth under current climate conditions without nitrogen fertilization to the growth with nitrogen fertilization under moderate and extreme changes. This choice mentions only growth without nitrogen fertilization under current conditions and moderate change and growth with nitrogen fertilization under extreme change, which don&rsquo;t provide a basis to determine whether higher nitrogen in the future will be able to offset reduced growth due to climate change. Choice C is incorrect. Although it accurately represents the data in the graph, this fact pattern doesn&rsquo;t support Ib&aacute;&ntilde;ez and colleagues&rsquo; conclusion that the decline in radial growth due to climate change will be partly offset by higher levels of atmospheric nitrogen, but only if change to the climate is moderate and not if it&rsquo;s extreme. The support needed would compare radial growth without adding nitrogen under current climate conditions to the growth with nitrogen fertilization under moderate and extreme changes. This choice mentions only the growth with and without nitrogen fertilization under moderate climate change and growth without nitrogen fertilization under extreme change, which don&rsquo;t provide a basis to determine whether higher nitrogen in the future will be able to offset reduced growth due to climate change.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323046,"updateDate":1730147323046}$SATQ$::jsonb, 1730147323046, 1730147323046),
    ($SATQ$628e1305$SATQ$, $SATQ$88e7e7d7-96c9-4086-8849-e0eb26f111ff$SATQ$::uuid, $SATQ$595e6dd8-2e8b-438b-9b14-b6c6e478ab29$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;Valia&rdquo; is a 1907 short story by Leonid Andreyev. In the story, the author emphasizes that the setting where the character Valia is reading is nearly silent: <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which quotation from &ldquo;Valia&rdquo; most effectively illustrates the claim?</p>$SATQ$, $SATQ$[{"id":"7a373b4b-93b7-4116-b867-5b02ff4f3dc2","content":"<p>&ldquo;The hand in which he carried his book was getting stiff with cold, but he would not ask his mother to take the book from him.&rdquo;</p>"},{"id":"d4280b34-e35c-4d47-8a85-8c561beaf2d1","content":"<p>&ldquo;Valia was reading a huge, very huge book, almost half as large as himself.&rdquo;</p>"},{"id":"88528a09-e01a-4ca9-8bc9-27aaae7a1bd0","content":"<p>&ldquo;Valia approached the window and examined the toys.&rdquo;</p>"},{"id":"b1f33ed4-aa3c-4c98-ba2e-92f3696f73b5","content":"<p>&ldquo;Everything in the room was quiet, so quiet that the only thing to be heard was the rustling of the pages he turned.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["b1f33ed4-aa3c-4c98-ba2e-92f3696f73b5"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because this quotation most effectively illustrates the claim that the author emphasizes the near silence of the setting where the character Valia is reading. In the quotation, the author highlights the near silence of the setting by twice using the word &ldquo;quiet&rdquo; to describe the room. The author also calls attention to the fact that Valia is reading in a nearly silent setting by noting that the only sound to be heard is that of the pages being turned. </p><p>Choice A is incorrect because this quotation suggests that Valia is in a chilly setting that causes his hand to become cold, not that he&rsquo;s in a nearly silent setting. Choice B is incorrect because this quotation emphasizes the size of the book Valia is reading, not a quality of the setting where he&rsquo;s reading it. Choice C is incorrect because this quotation describes Valia approaching a window and looking at toys, not reading in a quiet setting. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TXT-E005$SATQ$, $SATQ$$SATQ$, $SATQ$15111c6e-bb33-4572-a71a-03ceffa7d832$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"628e1305","external_id":"88e7e7d7-96c9-4086-8849-e0eb26f111ff","vaultid":"595e6dd8-2e8b-438b-9b14-b6c6e478ab29","uId":"71e86aeb-a08b-4fe0-8993-8b9164e7dd5d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>&ldquo;Valia&rdquo; is a 1907 short story by Leonid Andreyev. In the story, the author emphasizes that the setting where the character Valia is reading is nearly silent: <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which quotation from &ldquo;Valia&rdquo; most effectively illustrates the claim?</p>","answerOptions":[{"id":"7a373b4b-93b7-4116-b867-5b02ff4f3dc2","content":"<p>&ldquo;The hand in which he carried his book was getting stiff with cold, but he would not ask his mother to take the book from him.&rdquo;</p>"},{"id":"d4280b34-e35c-4d47-8a85-8c561beaf2d1","content":"<p>&ldquo;Valia was reading a huge, very huge book, almost half as large as himself.&rdquo;</p>"},{"id":"88528a09-e01a-4ca9-8bc9-27aaae7a1bd0","content":"<p>&ldquo;Valia approached the window and examined the toys.&rdquo;</p>"},{"id":"b1f33ed4-aa3c-4c98-ba2e-92f3696f73b5","content":"<p>&ldquo;Everything in the room was quiet, so quiet that the only thing to be heard was the rustling of the pages he turned.&rdquo;</p>"}],"keys":["b1f33ed4-aa3c-4c98-ba2e-92f3696f73b5"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because this quotation most effectively illustrates the claim that the author emphasizes the near silence of the setting where the character Valia is reading. In the quotation, the author highlights the near silence of the setting by twice using the word &ldquo;quiet&rdquo; to describe the room. The author also calls attention to the fact that Valia is reading in a nearly silent setting by noting that the only sound to be heard is that of the pages being turned. </p><p>Choice A is incorrect because this quotation suggests that Valia is in a chilly setting that causes his hand to become cold, not that he&rsquo;s in a nearly silent setting. Choice B is incorrect because this quotation emphasizes the size of the book Valia is reading, not a quality of the setting where he&rsquo;s reading it. Choice C is incorrect because this quotation describes Valia approaching a window and looking at toys, not reading in a quiet setting. </p>","parenttemplatename":"OSP-KA-TXT-E005","parenttemplateid":"","templateclusterid":"15111c6e-bb33-4572-a71a-03ceffa7d832","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959376,"updateDate":1691007959376}$SATQ$::jsonb, 1691007959376, 1691007959376),
    ($SATQ$6317295c$SATQ$, $SATQ$7a33ed6a-f554-4d71-a236-4b61dee1e053$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Properties of Select Rotating Radio Transients</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Name</th><th scope="col" style="text-align: center;vertical-align: bottom;">Right ascension (hours)</th><th scope="col" style="text-align: center;vertical-align: bottom;">Period (seconds)</th><th scope="col" style="text-align: center;vertical-align: bottom;">Frequency (hertz)</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">J0545-03</th><td style="text-align: center;">5<span data-ssml-say-as="characters">:</span>45</td><td style="text-align: center;">1.074</td><td style="text-align: center;">0.931</td></tr><tr><th scope="row" style="text-align: left;">J1654-2335</th><td style="text-align: center;">16<span data-ssml-say-as="characters">:</span>54<span data-ssml-say-as="characters">:</span>03</td><td style="text-align: center;">0.545</td><td style="text-align: center;">1.834</td></tr><tr><th scope="row" style="text-align: left;">J0103+54</th><td style="text-align: center;">1<span data-ssml-say-as="characters">:</span>03<span data-ssml-say-as="characters">:</span>37</td><td style="text-align: center;">0.354</td><td style="text-align: center;">2.822</td></tr><tr><th scope="row" style="text-align: left;">J0121+53</th><td style="text-align: center;">1<span data-ssml-say-as="characters">:</span>21</td><td style="text-align: center;">2.725</td><td style="text-align: center;">0.367</td></tr><tr><th scope="row" style="text-align: left;">J0614-03</th><td style="text-align: center;">6<span data-ssml-say-as="characters">:</span>15</td><td style="text-align: center;">0.136</td><td style="text-align: center;">7.353</td></tr></tbody></table></figure></p>
<p>A student is researching rotating radio transients (RRATs), a subclass of pulsar stars characterized by short pulses of radio waves. The time between consecutive pulses of an RRAT is referred to as a period. Looking at the table, the student determines that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the statement?</p>$SATQ$, $SATQ$[{"id":"28b16a07-2331-41bd-a1b5-c6c4e444c9cd","content":"<p>J0614-03 has the shortest amount of time between consecutive pulses of all the RRATs in the table.</p>"},{"id":"9a5ba297-2d3e-4adb-910f-a66822b5a2c1","content":"<p>J0545-03 and J0121+53 have the same amount of time between consecutive pulses.</p>"},{"id":"d47a2ada-c1ac-484c-bb44-c8898ef25678","content":"<p>J1654-2335 has the longest amount of time between consecutive pulses of all the RRATs in the table.</p>"},{"id":"c88a42e9-de03-4e13-8b76-0b6bca369aad","content":"<p>J0103+54 and J0121+53 both have more than one second of time between consecutive pulses.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["28b16a07-2331-41bd-a1b5-c6c4e444c9cd"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately uses data from the table to complete the statement about certain rotating radio transients (RRATs). The table contains information about the right ascensions, periods, and frequencies of various pulsar stars called RRATs. According to the text, the period of an RRAT is defined as the time between consecutive pulses. The table shows that the period of RRAT J0614-03 is 0.136 seconds, which is the lowest number of all the periods of the RRATs listed in the table. If the period is the time between consecutive pulses, and J0614-03 has the shortest period, then J0614-03 has the shortest amount of time between consecutive pulses of all the RRATs in the table.</p><p>Choice B is incorrect because according to the table, J0545-03 has a period of 1.074 seconds and J0121+53 has a period of 2.725 seconds. According to the text, the period of an RRAT is the time between consecutive pulses. Therefore, since J0545-03 and J0121+53 have different periods, they do not have the same amount of time between consecutive pulses. Choice C is incorrect because according to the table, J1654-2335 has a period of 0.545 seconds, which is not the longest period of all the RRATs listed in the table. According to the text, the period of an RRAT is the time between consecutive pulses, and both J0545-03 and J0121+53 have longer periods than J1654-2335, so J1654-2335 does not have the longest time between consecutive pulses of all the RRATs in the table. Choice D is incorrect because according to the table, J0103+54 has a period of 0.354 seconds, and J0121+53 has a period of 2.725 seconds. According to the text, the period of an RRAT is the time between consecutive pulses, and only J0121+53 has more than one second of time between consecutive pulses, not J0103+54.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6317295c","external_id":"7a33ed6a-f554-4d71-a236-4b61dee1e053","vaultid":null,"uId":"f94533ed-3b93-41cd-a918-4b77e806c300","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Properties of Select Rotating Radio Transients</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Name</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Right ascension (hours)</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Period (seconds)</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Frequency (hertz)</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">J0545-03</th><td style=\"text-align: center;\">5<span data-ssml-say-as=\"characters\">:</span>45</td><td style=\"text-align: center;\">1.074</td><td style=\"text-align: center;\">0.931</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">J1654-2335</th><td style=\"text-align: center;\">16<span data-ssml-say-as=\"characters\">:</span>54<span data-ssml-say-as=\"characters\">:</span>03</td><td style=\"text-align: center;\">0.545</td><td style=\"text-align: center;\">1.834</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">J0103+54</th><td style=\"text-align: center;\">1<span data-ssml-say-as=\"characters\">:</span>03<span data-ssml-say-as=\"characters\">:</span>37</td><td style=\"text-align: center;\">0.354</td><td style=\"text-align: center;\">2.822</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">J0121+53</th><td style=\"text-align: center;\">1<span data-ssml-say-as=\"characters\">:</span>21</td><td style=\"text-align: center;\">2.725</td><td style=\"text-align: center;\">0.367</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">J0614-03</th><td style=\"text-align: center;\">6<span data-ssml-say-as=\"characters\">:</span>15</td><td style=\"text-align: center;\">0.136</td><td style=\"text-align: center;\">7.353</td></tr></tbody></table></figure></p>\n<p>A student is researching rotating radio transients (RRATs), a subclass of pulsar stars characterized by short pulses of radio waves. The time between consecutive pulses of an RRAT is referred to as a period. Looking at the table, the student determines that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the statement?</p>","answerOptions":[{"id":"28b16a07-2331-41bd-a1b5-c6c4e444c9cd","content":"<p>J0614-03 has the shortest amount of time between consecutive pulses of all the RRATs in the table.</p>"},{"id":"9a5ba297-2d3e-4adb-910f-a66822b5a2c1","content":"<p>J0545-03 and J0121+53 have the same amount of time between consecutive pulses.</p>"},{"id":"d47a2ada-c1ac-484c-bb44-c8898ef25678","content":"<p>J1654-2335 has the longest amount of time between consecutive pulses of all the RRATs in the table.</p>"},{"id":"c88a42e9-de03-4e13-8b76-0b6bca369aad","content":"<p>J0103+54 and J0121+53 both have more than one second of time between consecutive pulses.</p>"}],"keys":["28b16a07-2331-41bd-a1b5-c6c4e444c9cd"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately uses data from the table to complete the statement about certain rotating radio transients (RRATs). The table contains information about the right ascensions, periods, and frequencies of various pulsar stars called RRATs. According to the text, the period of an RRAT is defined as the time between consecutive pulses. The table shows that the period of RRAT J0614-03 is 0.136 seconds, which is the lowest number of all the periods of the RRATs listed in the table. If the period is the time between consecutive pulses, and J0614-03 has the shortest period, then J0614-03 has the shortest amount of time between consecutive pulses of all the RRATs in the table.</p><p>Choice B is incorrect because according to the table, J0545-03 has a period of 1.074 seconds and J0121+53 has a period of 2.725 seconds. According to the text, the period of an RRAT is the time between consecutive pulses. Therefore, since J0545-03 and J0121+53 have different periods, they do not have the same amount of time between consecutive pulses. Choice C is incorrect because according to the table, J1654-2335 has a period of 0.545 seconds, which is not the longest period of all the RRATs listed in the table. According to the text, the period of an RRAT is the time between consecutive pulses, and both J0545-03 and J0121+53 have longer periods than J1654-2335, so J1654-2335 does not have the longest time between consecutive pulses of all the RRATs in the table. Choice D is incorrect because according to the table, J0103+54 has a period of 0.354 seconds, and J0121+53 has a period of 2.725 seconds. According to the text, the period of an RRAT is the time between consecutive pulses, and only J0121+53 has more than one second of time between consecutive pulses, not J0103+54.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669209,"updateDate":1743430669209}$SATQ$::jsonb, 1743430669209, 1743430669209),
    ($SATQ$63e7799d$SATQ$, $SATQ$af31476c-fbc2-4fe8-8656-e63f24aafb95$SATQ$::uuid, $SATQ$4c551828-a404-4435-b9e1-83c087c66356$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In vertical inheritance, parents pass genes to their offspring, but in horizontal transfer (HT), one species, often bacteria, passes genetic material to an unrelated species. In a 2022 study, herpetologist Atsushi Kurabayashi and his team investigated HT in multicellular organisms&mdash;namely, snakes and frogs in Madagascar. The team detected <em>BovB</em>&mdash;a gene transmitted vertically in snakes&mdash;in many frog species. The apparent direction of gene transfer seems counterintuitive because frogs usually don&rsquo;t survive encounters with snakes and so wouldn&rsquo;t be able to transmit the newly acquired gene to offspring, but the team concluded that <em>BovB </em>is indeed transmitted from snakes to frogs, either directly or indirectly, via HT.</p>$SATQ$, $SATQ$<p>Which finding, if true, would most directly support the team&rsquo;s conclusion?</p>$SATQ$, $SATQ$[{"id":"cf296b73-17ee-4e35-b5e5-bb69c10f392e","content":"<p><em>BovB </em>can be transmitted across frog species through HT.</p>"},{"id":"1395a19a-1aa8-44a8-a3f8-b3699587ebf1","content":"<p>Parasites known to feed on species of snakes and frogs in which the <em>BovB</em> gene occurs also carry <em>BovB</em>.&nbsp;</p>"},{"id":"af05db83-e34b-4621-af01-0b4f71db454c","content":"<p><em>BovB</em> cannot be reliably transmitted from a snake species to bacteria that are usually encountered by frog species.</p>"},{"id":"59305461-4216-4053-a786-75a40ace60d7","content":"<p>Frog species with <em>BovB</em> show few discernible advantages as compared with frog species that do not carry <em>BovB</em>.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["1395a19a-1aa8-44a8-a3f8-b3699587ebf1"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. If there are parasites that feed on both snakes and frogs, they could carry <em>BovB</em> from snakes to frogs. HT could occur &ldquo;indirectly&rdquo; through those encounters, which frogs are more likely to survive than snake encounters. </p><p>Choice A is incorrect. The team&rsquo;s conclusion specifically argues that <em>BovB</em> is transmitted from snakes to frogs via HT, and this choice doesn&rsquo;t mention snakes. Choice C is incorrect. The team argues that <em>BovB</em> is transmitted from snakes to frogs via HT, and this answer choice discusses a scenario in which the gene is not transmitted. Choice D is incorrect. Whether or not frog species with <em>BovB</em> are advantaged isn&rsquo;t relevant to the team&rsquo;s conclusion about how the gene is transmitted. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TXT-H009$SATQ$, $SATQ$$SATQ$, $SATQ$32cab8ed-f0b2-4d7b-8cf1-3e8cb57df6fc$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"63e7799d","external_id":"af31476c-fbc2-4fe8-8656-e63f24aafb95","vaultid":"4c551828-a404-4435-b9e1-83c087c66356","uId":"7d3aa104-ff7c-4fdd-8bc8-43196f8dfd59","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>In vertical inheritance, parents pass genes to their offspring, but in horizontal transfer (HT), one species, often bacteria, passes genetic material to an unrelated species. In a 2022 study, herpetologist Atsushi Kurabayashi and his team investigated HT in multicellular organisms&mdash;namely, snakes and frogs in Madagascar. The team detected <em>BovB</em>&mdash;a gene transmitted vertically in snakes&mdash;in many frog species. The apparent direction of gene transfer seems counterintuitive because frogs usually don&rsquo;t survive encounters with snakes and so wouldn&rsquo;t be able to transmit the newly acquired gene to offspring, but the team concluded that <em>BovB </em>is indeed transmitted from snakes to frogs, either directly or indirectly, via HT.</p>","stem":"<p>Which finding, if true, would most directly support the team&rsquo;s conclusion?</p>","answerOptions":[{"id":"cf296b73-17ee-4e35-b5e5-bb69c10f392e","content":"<p><em>BovB </em>can be transmitted across frog species through HT.</p>"},{"id":"1395a19a-1aa8-44a8-a3f8-b3699587ebf1","content":"<p>Parasites known to feed on species of snakes and frogs in which the <em>BovB</em> gene occurs also carry <em>BovB</em>.&nbsp;</p>"},{"id":"af05db83-e34b-4621-af01-0b4f71db454c","content":"<p><em>BovB</em> cannot be reliably transmitted from a snake species to bacteria that are usually encountered by frog species.</p>"},{"id":"59305461-4216-4053-a786-75a40ace60d7","content":"<p>Frog species with <em>BovB</em> show few discernible advantages as compared with frog species that do not carry <em>BovB</em>.</p>"}],"keys":["1395a19a-1aa8-44a8-a3f8-b3699587ebf1"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. If there are parasites that feed on both snakes and frogs, they could carry <em>BovB</em> from snakes to frogs. HT could occur &ldquo;indirectly&rdquo; through those encounters, which frogs are more likely to survive than snake encounters. </p><p>Choice A is incorrect. The team&rsquo;s conclusion specifically argues that <em>BovB</em> is transmitted from snakes to frogs via HT, and this choice doesn&rsquo;t mention snakes. Choice C is incorrect. The team argues that <em>BovB</em> is transmitted from snakes to frogs via HT, and this answer choice discusses a scenario in which the gene is not transmitted. Choice D is incorrect. Whether or not frog species with <em>BovB</em> are advantaged isn&rsquo;t relevant to the team&rsquo;s conclusion about how the gene is transmitted. </p>","parenttemplatename":"OSP-KA-TXT-H009","parenttemplateid":"","templateclusterid":"32cab8ed-f0b2-4d7b-8cf1-3e8cb57df6fc","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959376,"updateDate":1691007959376}$SATQ$::jsonb, 1691007959376, 1691007959376),
    ($SATQ$6409016a$SATQ$, $SATQ$b81c7d76-65b5-423e-9f26-72f78b04f576$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>The Household, Income and Labour Dynamics in Australia Survey (HILDA) examines trends in economic well-being among 25,000 people in Australia unfolding over many years. As is true of most longitudinal studies, this need for years of data collection results in high costs. By contrast, a relatively straightforward fitness study, such as one that is merely trying to identify the percentage of regular exercisers in a city who do weight training, may not need a large budget because <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"d3dda594-fe36-47d5-b681-e7680337a2a3","content":"<p>longitudinal methods are probably suitable for the fitness study.</p>"},{"id":"0e6ebbfa-b8ea-4ec2-9083-1d24a54f80a9","content":"<p>it would be easy for HILDA researchers to add questions to their economic well-being study.</p>"},{"id":"09ff4ae0-b0e1-4384-b727-deb98ae795be","content":"<p>25,000 people is more than enough for HILDA to find trends in economic well-being.</p>"},{"id":"5c547301-fc80-4571-9efd-958e40fef7d5","content":"<p>the fitness study can be done well without years of data collection.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["5c547301-fc80-4571-9efd-958e40fef7d5"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the costs of studies. The text indicates that HILDA is a longitudinal study&mdash;it involves repeated observations over a long time&mdash;and that the "need for years of data collection" is what causes it and most other longitudinal studies to have high costs. The text then contrasts such studies with more straightforward studies, using the example of a fitness study that wants only to find out how many regular exercisers in a particular location do weight training, that may not demand a large budget. The contrast emphasized in the text most directly suggests that the fitness study may cost less than a study like HILDA because the fitness study aims only to determine a current percentage and thus can be completed well without extending data collection over years.</p><p>Choice A is incorrect because the text explicitly introduces the idea of a less expensive, straightforward fitness study as a contrast to many longitudinal studies that, like HILDA, have high costs because they require data collection over many years. The fitness study is described as trying merely to gather information about a current behavior (how many regular exercisers do weight training) rather than track trends over time, which suggests that costs could remain low because expensive longitudinal methods would not be needed, not because they would be suitable. Choice B is incorrect because the idea that HILDA researchers could easily add questions to their study might be relevant to the costs of that survey but would be completely irrelevant as an explanation for why an unrelated fitness study may not need a large budget; the studies have no direct bearing on each other. Choice C is incorrect because the idea that HILDA involves more people than necessary would be relevant to the costs of that survey but would be completely irrelevant as an explanation for why an unrelated fitness study may not need a large budget; the studies have no direct bearing on each other.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6409016a","external_id":"b81c7d76-65b5-423e-9f26-72f78b04f576","vaultid":null,"uId":"60d8aaf8-78db-45ac-b070-62a2446f7784","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>The Household, Income and Labour Dynamics in Australia Survey (HILDA) examines trends in economic well-being among 25,000 people in Australia unfolding over many years. As is true of most longitudinal studies, this need for years of data collection results in high costs. By contrast, a relatively straightforward fitness study, such as one that is merely trying to identify the percentage of regular exercisers in a city who do weight training, may not need a large budget because <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"d3dda594-fe36-47d5-b681-e7680337a2a3","content":"<p>longitudinal methods are probably suitable for the fitness study.</p>"},{"id":"0e6ebbfa-b8ea-4ec2-9083-1d24a54f80a9","content":"<p>it would be easy for HILDA researchers to add questions to their economic well-being study.</p>"},{"id":"09ff4ae0-b0e1-4384-b727-deb98ae795be","content":"<p>25,000 people is more than enough for HILDA to find trends in economic well-being.</p>"},{"id":"5c547301-fc80-4571-9efd-958e40fef7d5","content":"<p>the fitness study can be done well without years of data collection.</p>"}],"keys":["5c547301-fc80-4571-9efd-958e40fef7d5"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the costs of studies. The text indicates that HILDA is a longitudinal study&mdash;it involves repeated observations over a long time&mdash;and that the \"need for years of data collection\" is what causes it and most other longitudinal studies to have high costs. The text then contrasts such studies with more straightforward studies, using the example of a fitness study that wants only to find out how many regular exercisers in a particular location do weight training, that may not demand a large budget. The contrast emphasized in the text most directly suggests that the fitness study may cost less than a study like HILDA because the fitness study aims only to determine a current percentage and thus can be completed well without extending data collection over years.</p><p>Choice A is incorrect because the text explicitly introduces the idea of a less expensive, straightforward fitness study as a contrast to many longitudinal studies that, like HILDA, have high costs because they require data collection over many years. The fitness study is described as trying merely to gather information about a current behavior (how many regular exercisers do weight training) rather than track trends over time, which suggests that costs could remain low because expensive longitudinal methods would not be needed, not because they would be suitable. Choice B is incorrect because the idea that HILDA researchers could easily add questions to their study might be relevant to the costs of that survey but would be completely irrelevant as an explanation for why an unrelated fitness study may not need a large budget; the studies have no direct bearing on each other. Choice C is incorrect because the idea that HILDA involves more people than necessary would be relevant to the costs of that survey but would be completely irrelevant as an explanation for why an unrelated fitness study may not need a large budget; the studies have no direct bearing on each other.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061191,"updateDate":1755117061191}$SATQ$::jsonb, 1755117061191, 1755117061191),
    ($SATQ$645fd11a$SATQ$, $SATQ$e106d6c6-3728-41aa-983d-844c3f37d99e$SATQ$::uuid, $SATQ$e3f31403-2fc6-496a-ac99-afd9db5beff2$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<figure class="image"><svg aria-label="Bar graph titled Average Number of Individuals Reporting Directly to CEOs. The horizontal axis is labeled Years. 3 data categories are shown. The vertical axis is labeled Average number of individuals directly reporting to CEO. It ranges from 0 to 7 in increments of 1. Refer to long description." height="479.62939453125" role="img" viewbox="0 0 400 479.62939453125" width="400" xmlns="http://www.w3.org/2000/svg"><g data-name="Layer 1" id="ed420550-79eb-48d4-af01-cd27cdd08afd"><defs>
